require('dotenv').config({path:path.join(__dirname,'.env')});
const express=require('express'),crypto=require('crypto'),pool=require('./config/db');
const app=express(),PORT=process.env.PORT||3000,SECRET=process.env.TOKEN_SECRET||'ctu-main-change-this-secret';
app.disable('x-powered-by'); app.use(express.json({limit:'1mb'}));
const wrap=fn=>(req,res,next)=>Promise.resolve(fn(req,res,next)).catch(next), b64=v=>Buffer.from(JSON.stringify(v)).toString('base64url');
const token=u=>{const p=b64({id:u.id,role:u.role,exp:Date.now()+28800000});return p+'.'+crypto.createHmac('sha256',SECRET).update(p).digest('base64url')};
function auth(req,res,next){try{const [p,s]=(req.headers.authorization||'').replace(/^Bearer /,'').split('.'),e=crypto.createHmac('sha256',SECRET).update(p||'').digest('base64url');if(!s||s.length!==e.length||!crypto.timingSafeEqual(Buffer.from(s),Buffer.from(e)))throw 0;req.user=JSON.parse(Buffer.from(p,'base64url'));if(req.user.exp<Date.now())throw 0;next()}catch{res.status(401).json({message:'Your session has expired. Please sign in again.'})}}
const allow=(...r)=>(req,res,next)=>r.includes(req.user.role)?next():res.status(403).json({message:'You do not have permission to perform this action.'});
async function audit(uid,action,type,id,details={}){await pool.query('INSERT INTO audit_logs(user_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5)',[uid,action,type,String(id||''),details])}
const validDays=new Set(['M','T','W','Th','F','Sa']);
function normalizeDays(days){const value=Array.isArray(days)?days:[];return [...new Set(value)].filter(day=>validDays.has(day))}
async function saveAcademicBlock(client,body,blockId=null){
  const {program_id,year_level,code,classification='regular',capacity=40,assignments}=body;
  if(!program_id||!year_level||!code||!['regular','irregular'].includes(classification)||!Array.isArray(assignments)||!assignments.length){const e=new Error('Program, year level, section code, classification, and at least one course assignment are required.');e.status=400;throw e}
  if(new Set(assignments.map(x=>String(x.course_id))).size!==assignments.length){const e=new Error('A course can only appear once in a block section.');e.status=400;throw e}
  const term=(await client.query('SELECT id FROM academic_terms WHERE is_current LIMIT 1')).rows[0];if(!term){const e=new Error('Create a current academic term first.');e.status=400;throw e}
  let id=blockId;
  if(id){const used=await client.query(`SELECT 1 FROM enrollments WHERE block_id=$1 AND status IN('pending','enrolled','completed') LIMIT 1`,[id]);if(used.rowCount){const e=new Error('This block already has active enrollments and its course assignments cannot be replaced.');e.status=409;throw e}await client.query(`UPDATE academic_blocks SET program_id=$1,year_level=$2,code=UPPER($3),classification=$4,capacity=$5,is_active=TRUE WHERE id=$6 AND term_id=$7`,[program_id,year_level,code.trim(),classification,capacity,id,term.id]);await client.query('DELETE FROM class_sections WHERE block_id=$1',[id])}
  else id=(await client.query(`INSERT INTO academic_blocks(term_id,program_id,year_level,code,classification,capacity)VALUES($1,$2,$3,UPPER($4),$5,$6)RETURNING id`,[term.id,program_id,year_level,code.trim(),classification,capacity])).rows[0].id;
  for(const item of assignments){
    const days=normalizeDays(item.meeting_days);if(!item.course_id||!item.teacher_id||!item.room||!days.length||!item.start_time||!item.end_time){const e=new Error('Every course requires a teacher, room, meeting day, start time, and end time.');e.status=400;throw e}if(item.start_time>=item.end_time){const e=new Error('Every class end time must be later than its start time.');e.status=400;throw e}
    const course=await client.query('SELECT id FROM courses WHERE id=$1 AND program_id=$2 AND is_active',[item.course_id,program_id]);if(!course.rowCount){const e=new Error('Every assigned course must belong to the selected program.');e.status=400;throw e}
    const teacher=await client.query(`SELECT t.id FROM teachers t JOIN users u ON u.id=t.user_id WHERE t.id=$1 AND u.is_active`,[item.teacher_id]);if(!teacher.rowCount){const e=new Error('Every course must have an active teacher assignment.');e.status=400;throw e}
    const conflict=await client.query(`SELECT c.code course_code,cs.section_code,cs.days,TO_CHAR(cs.start_time,'HH12:MI AM') start_time,TO_CHAR(cs.end_time,'HH12:MI AM') end_time FROM class_sections cs JOIN courses c ON c.id=cs.course_id WHERE cs.term_id=$1 AND cs.meeting_days&&$2::text[] AND cs.start_time<$3::time AND cs.end_time>$4::time AND (cs.teacher_id=$5 OR LOWER(cs.room)=LOWER($6)) LIMIT 1`,[term.id,days,item.end_time,item.start_time,item.teacher_id,item.room]);
    if(conflict.rowCount){const x=conflict.rows[0],e=new Error(`Schedule conflict with ${x.course_code} (${x.section_code}) on ${x.days}, ${x.start_time}–${x.end_time}. Change the teacher, room, or time.`);e.status=409;throw e}
    await client.query(`INSERT INTO class_sections(term_id,course_id,teacher_id,section_code,room,days,meeting_days,start_time,end_time,capacity,block_id)VALUES($1,$2,$3,(SELECT code FROM academic_blocks WHERE id=$4),$5,$6,$7,$8,$9,$10,$4)`,[term.id,item.course_id,item.teacher_id,id,item.room,days.join('/'),days,item.start_time,item.end_time,capacity]);
  }
  return id;
}
const userSql=`SELECT u.id,u.employee_or_student_no,u.email,u.role,u.first_name,u.middle_name,u.last_name,u.phone,u.address,u.avatar_color,u.is_active,u.last_login_at,u.created_at FROM users u`;

