app.post('/api/student/enrollment',auth,allow('student'),wrap(async(req,res,next)=>{const q=await pool.query(`SELECT e.status FROM enrollments e JOIN students s ON s.id=e.student_id JOIN academic_terms t ON t.id=e.term_id WHERE s.user_id=$1 AND t.is_current`,[req.user.id]);if(['enrolled','completed'].includes(q.rows[0]?.status))return res.status(409).json({message:'An approved enrollment cannot be changed online. Contact the Registrar for an adjustment.'});next()}));
app.patch('/api/registrar/admissions/:id',auth,allow('registrar','admin'),wrap(async(req,res,next)=>{const q=await pool.query('SELECT status FROM admission_applications WHERE id=$1',[req.params.id]);if(q.rows[0]?.status==='approved'&&req.body.status!=='approved')return res.status(409).json({message:'An approved admission cannot be reversed from the portal because its student account is already active.'});next()}));
app.patch('/api/registrar/enrollments/:id',auth,allow('registrar','admin'),wrap(async(req,res,next)=>{const allowed=['pending','enrolled','rejected','completed','dropped'];if(!allowed.includes(req.body.status))return res.status(400).json({message:'Select a valid enrollment status.'});if(req.body.status!=='enrolled')return next();const q=await pool.query(`SELECT e.block_id,COUNT(ei.id)::int courses FROM enrollments e LEFT JOIN enrollment_items ei ON ei.enrollment_id=e.id WHERE e.id=$1 GROUP BY e.id`,[req.params.id]);if(!q.rowCount)return res.status(404).json({message:'Enrollment record not found.'});if(!q.rows[0].block_id||!q.rows[0].courses)return res.status(409).json({message:'This enrollment has no selected block section or attached courses and cannot be approved.'});next()}));
app.patch('/api/registrar/admissions/:id',auth,allow('registrar','admin'),wrap(async(req,res,next)=>{if(req.body.status!=='approved')return next();const q=await pool.query(`SELECT a.id,a.student_id,a.program_id,a.applicant_type,a.birth_date,a.gender,a.guardian_name,a.guardian_phone,u.id user_id,u.role,s.id existing_student_id FROM admission_applications a LEFT JOIN users u ON LOWER(u.email)=LOWER(a.email) LEFT JOIN students s ON s.user_id=u.id WHERE a.id=$1`,[req.params.id]),r=q.rows[0];if(!r||r.student_id||!r.user_id)return next();if(r.role!=='student')return res.status(409).json({message:'This email is already assigned to a non-student portal account. Use a different applicant email.'});let studentId=r.existing_student_id;if(!studentId)studentId=(await pool.query(`INSERT INTO students(user_id,program_id,year_level,section,admission_year,birth_date,gender,guardian_name,guardian_phone,admission_type,enrollment_classification)VALUES($1,$2,1,'TBA',EXTRACT(YEAR FROM CURRENT_DATE),$3,$4,$5,$6,$7,CASE WHEN $7::varchar='transferee' THEN 'irregular' ELSE 'regular' END)RETURNING id`,[r.user_id,r.program_id,r.birth_date,r.gender,r.guardian_name,r.guardian_phone,r.applicant_type])).rows[0].id;await pool.query('UPDATE admission_applications SET student_id=$1,credentials_claimed_at=COALESCE(credentials_claimed_at,NOW()),updated_at=NOW() WHERE id=$2',[studentId,r.id]);next()}));
app.patch('/api/registrar/admissions/:id',auth,allow('registrar','admin'),wrap(async(req,res,next)=>{if(req.body.status!=='approved')return next();const q=await pool.query(`SELECT a.student_id,t.id term_id FROM admission_applications a CROSS JOIN academic_terms t WHERE a.id=$1 AND a.student_id IS NOT NULL AND t.is_current`,[req.params.id]);if(q.rowCount)await pool.query(`INSERT INTO enrollments(student_id,term_id,status,enrollment_type,total_units,remarks)VALUES($1,$2,'draft',(SELECT enrollment_classification FROM students WHERE id=$1),0,'Complete subject selection in the student portal.')ON CONFLICT(student_id,term_id)DO NOTHING`,[q.rows[0].student_id,q.rows[0].term_id]);next()}));

app.get('/api/dashboard',auth,wrap(async(req,res)=>{let stats={},activity=[];const r=req.user.role;if(r==='student'){const sid=(await pool.query('SELECT id FROM students WHERE user_id=$1',[req.user.id])).rows[0]?.id;stats=(await pool.query(`SELECT (SELECT COUNT(*) FROM enrollment_items ei JOIN enrollments e ON e.id=ei.enrollment_id WHERE e.student_id=$1 AND e.status='enrolled') courses,(SELECT COALESCE(ROUND(AVG(COALESCE(final_grade,midterm_grade)),2),0) FROM enrollment_items ei JOIN enrollments e ON e.id=ei.enrollment_id WHERE e.student_id=$1) gwa,(SELECT COALESCE(SUM(b.amount-COALESCE((SELECT SUM(p.amount)FROM payments p WHERE p.billing_item_id=b.id AND p.status='posted'),0)),0) FROM billing_items b WHERE b.student_id=$1) balance,(SELECT COUNT(*) FROM document_requests WHERE student_id=$1 AND status NOT IN('released','rejected')) requests`,[sid])).rows[0]}else if(r==='teacher'){const tid=(await pool.query('SELECT id FROM teachers WHERE user_id=$1',[req.user.id])).rows[0]?.id;stats=(await pool.query(`SELECT COUNT(DISTINCT cs.id) classes,COUNT(DISTINCT e.student_id) students,COUNT(*) FILTER(WHERE ei.final_grade IS NULL) pending_grades,COALESCE(ROUND(AVG(ei.attendance_percent),1),0) attendance FROM class_sections cs LEFT JOIN enrollment_items ei ON ei.class_section_id=cs.id LEFT JOIN enrollments e ON e.id=ei.enrollment_id WHERE cs.teacher_id=$1`,[tid])).rows[0]}else if(r==='registrar')stats=(await pool.query(`SELECT (SELECT COUNT(*) FROM students) students,(SELECT COUNT(*) FROM enrollments WHERE status='pending') pending_enrollments,(SELECT COUNT(*) FROM document_requests WHERE status IN('pending','processing')) document_requests,(SELECT COUNT(*) FROM programs WHERE is_active) programs`)).rows[0];else if(r==='cashier')stats=(await pool.query(`SELECT (SELECT COALESCE(SUM(amount),0) FROM payments WHERE paid_at::date=CURRENT_DATE AND status='posted') today_collection,(SELECT COUNT(*) FROM payments WHERE paid_at::date=CURRENT_DATE AND status='posted') transactions,(SELECT COALESCE(SUM(b.amount-COALESCE((SELECT SUM(p.amount)FROM payments p WHERE p.billing_item_id=b.id AND p.status='posted'),0)),0) FROM billing_items b) receivables,(SELECT COUNT(DISTINCT student_id) FROM billing_items WHERE status!='Paid') accounts_due`)).rows[0];else if(r==='clinic')stats=(await pool.query(`SELECT COUNT(*) FILTER(WHERE visited_at::date=CURRENT_DATE) visits_today,COUNT(*) FILTER(WHERE visited_at>=date_trunc('month',CURRENT_DATE)) visits_month,COUNT(DISTINCT student_id) patients,COUNT(*) FILTER(WHERE disposition ILIKE '%refer%') referrals FROM clinic_visits`)).rows[0];else{stats=(await pool.query(`SELECT (SELECT COUNT(*) FROM users WHERE is_active) users,(SELECT COUNT(*) FROM students) students,(SELECT COUNT(*) FROM teachers) faculty,(SELECT COUNT(*) FROM courses WHERE is_active) courses`)).rows[0];activity=(await pool.query(`SELECT a.*,u.first_name||' '||u.last_name user_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 8`)).rows}res.json({stats,activity})}));
