app.post('/api/admin/terms',auth,allow('admin'),wrap(async(req,res)=>{const b=req.body;if(!b.school_year||!b.semester||!b.starts_on||!b.ends_on)return res.status(400).json({message:'School year, semester, start date, and end date are required.'});const c=await pool.connect();try{await c.query('BEGIN');if(b.is_current)await c.query('UPDATE academic_terms SET is_current=FALSE');const q=await c.query(`INSERT INTO academic_terms(school_year,semester,starts_on,ends_on,enrollment_open,is_current)VALUES($1,$2,$3,$4,$5,$6)ON CONFLICT(school_year,semester)DO UPDATE SET starts_on=EXCLUDED.starts_on,ends_on=EXCLUDED.ends_on,enrollment_open=EXCLUDED.enrollment_open,is_current=EXCLUDED.is_current RETURNING *`,[b.school_year,b.semester,b.starts_on,b.ends_on,!!b.enrollment_open,!!b.is_current]);await c.query('COMMIT');await audit(req.user.id,'SAVED_ACADEMIC_TERM','academic_term',q.rows[0].id);res.status(201).json(q.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.post('/api/admin/courses',auth,allow('admin'),wrap(async(req,res)=>{const b=req.body;if(!b.program_id||!b.code||!b.title||!b.units||!b.year_level)return res.status(400).json({message:'Program, course code, title, units, and year level are required.'});const q=await pool.query(`INSERT INTO courses(program_id,code,title,units,lecture_hours,lab_hours,year_level,semester,prerequisite)VALUES($1,UPPER($2),$3,$4,$5,$6,$7,$8,$9)RETURNING *`,[b.program_id,b.code.trim(),b.title,b.units,b.lecture_hours||0,b.lab_hours||0,b.year_level,b.semester||'1st Semester',b.prerequisite||null]);await audit(req.user.id,'CREATED_COURSE','course',q.rows[0].id);res.status(201).json(q.rows[0])}));
app.get('/api/registrar/blocks',auth,allow('registrar','admin'),wrap(async(req,res)=>res.json((await pool.query(`SELECT b.id,b.code,b.year_level,b.classification,b.capacity,b.is_active,p.id program_id,p.code program_code,p.name program_name,t.school_year,t.semester,COUNT(cs.id)::int course_count,(SELECT COUNT(*)::int FROM enrollments e WHERE e.block_id=b.id AND e.status IN('pending','enrolled','completed')) enrolled,COALESCE(JSON_AGG(JSON_BUILD_OBJECT('id',cs.id,'course_id',c.id,'course_code',c.code,'course_title',c.title,'units',c.units,'teacher_id',te.id,'teacher',u.first_name||' '||u.last_name,'room',cs.room,'meeting_days',cs.meeting_days,'days',cs.days,'start_time',TO_CHAR(cs.start_time,'HH24:MI'),'end_time',TO_CHAR(cs.end_time,'HH24:MI')) ORDER BY cs.start_time,c.code)FILTER(WHERE cs.id IS NOT NULL),'[]') assignments FROM academic_blocks b JOIN programs p ON p.id=b.program_id JOIN academic_terms t ON t.id=b.term_id LEFT JOIN class_sections cs ON cs.block_id=b.id LEFT JOIN courses c ON c.id=cs.course_id LEFT JOIN teachers te ON te.id=cs.teacher_id LEFT JOIN users u ON u.id=te.user_id WHERE t.is_current GROUP BY b.id,p.id,t.id ORDER BY p.code,b.year_level,b.code`)).rows)));
app.post('/api/registrar/blocks',auth,allow('registrar','admin'),wrap(async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const id=await saveAcademicBlock(c,req.body);await c.query('COMMIT');await audit(req.user.id,'CREATED_BLOCK_SECTION','academic_block',id,{code:req.body.code});res.status(201).json({id})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.put('/api/registrar/blocks/:id',auth,allow('registrar','admin'),wrap(async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const id=await saveAcademicBlock(c,req.body,req.params.id);await c.query('COMMIT');await audit(req.user.id,'UPDATED_BLOCK_SECTION','academic_block',id,{code:req.body.code});res.json({id})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.patch('/api/registrar/blocks/:id/status',auth,allow('registrar','admin'),wrap(async(req,res)=>{if(!req.body.is_active){const used=await pool.query(`SELECT 1 FROM enrollments WHERE block_id=$1 AND status IN('pending','enrolled','completed') LIMIT 1`,[req.params.id]);if(used.rowCount)return res.status(409).json({message:'A block with active enrollments cannot be deactivated.'})}const q=await pool.query('UPDATE academic_blocks SET is_active=$1 WHERE id=$2 RETURNING id,is_active',[!!req.body.is_active,req.params.id]);await audit(req.user.id,'CHANGED_BLOCK_STATUS','academic_block',req.params.id,{active:!!req.body.is_active});res.json(q.rows[0])}));

app.get('/api/student/schedule',auth,allow('student'),wrap(async(req,res)=>res.json((await pool.query(`SELECT cs.id,c.code,c.title,c.units,cs.section_code,cs.room,cs.days,TO_CHAR(cs.start_time,'HH12:MI AM')start_time,TO_CHAR(cs.end_time,'HH12:MI AM')end_time,u.first_name||' '||u.last_name teacher FROM students s JOIN enrollments e ON e.student_id=s.id JOIN enrollment_items ei ON ei.enrollment_id=e.id JOIN class_sections cs ON cs.id=ei.class_section_id JOIN courses c ON c.id=cs.course_id LEFT JOIN teachers t ON t.id=cs.teacher_id LEFT JOIN users u ON u.id=t.user_id WHERE s.user_id=$1 AND e.status='enrolled' ORDER BY cs.start_time`,[req.user.id])).rows)));
