app.post('/api/student/documents',auth,allow('student'),wrap(async(req,res)=>{const sid=(await pool.query('SELECT id FROM students WHERE user_id=$1',[req.user.id])).rows[0]?.id,b=req.body;if(!b.document_type)return res.status(400).json({message:'Select a document type.'});const q=await pool.query('INSERT INTO document_requests(student_id,document_type,purpose,copies)VALUES($1,$2,$3,$4)RETURNING *',[sid,b.document_type,b.purpose,b.copies||1]);await audit(req.user.id,'REQUESTED_DOCUMENT','document_request',q.rows[0].id);res.status(201).json(q.rows[0])}));
app.get('/api/student/enrollment',auth,allow('student'),wrap(async(req,res)=>{const profile=(await pool.query(`SELECT s.id,s.program_id,s.year_level,s.enrollment_classification,p.code program_code FROM students s JOIN programs p ON p.id=s.program_id WHERE s.user_id=$1`,[req.user.id])).rows[0];if(!profile)return res.status(404).json({message:'Your student profile is incomplete. Contact the Registrar.'});const term=(await pool.query('SELECT * FROM academic_terms WHERE is_current LIMIT 1')).rows[0];if(!term)return res.status(404).json({message:'No active academic term is configured.'});const current=(await pool.query(`SELECT e.id,e.status,e.enrollment_type,e.total_units,e.block_id,b.code section_code,e.remarks,e.submitted_at FROM enrollments e LEFT JOIN academic_blocks b ON b.id=e.block_id WHERE e.student_id=$1 AND e.term_id=$2`,[profile.id,term.id])).rows[0]||null;const blocks=(await pool.query(`SELECT b.id,b.code,b.classification,b.year_level,b.capacity,(SELECT COUNT(*)::int FROM enrollments e WHERE e.block_id=b.id AND e.status IN('pending','enrolled')) occupied,ROUND(SUM(c.units),1) total_units,JSON_AGG(JSON_BUILD_OBJECT('code',c.code,'title',c.title,'units',c.units,'room',cs.room,'days',cs.days,'start_time',TO_CHAR(cs.start_time,'HH12:MI AM'),'end_time',TO_CHAR(cs.end_time,'HH12:MI AM'),'prerequisite',c.prerequisite) ORDER BY cs.start_time,c.code) courses FROM academic_blocks b JOIN class_sections cs ON cs.block_id=b.id JOIN courses c ON c.id=cs.course_id WHERE b.term_id=$1 AND b.program_id=$2 AND b.is_active AND b.classification=$4 AND ($4='irregular' OR b.year_level=$3) GROUP BY b.id ORDER BY b.code`,[term.id,profile.program_id,profile.year_level,profile.enrollment_classification])).rows;res.json({profile,term,current,blocks})}));
app.post('/api/student/enrollment',auth,allow('student'),wrap(async(req,res)=>{const b=req.body;if(!b.block_id)return res.status(400).json({message:'Choose one available section.'});const c=await pool.connect();try{await c.query('BEGIN');const s=(await c.query('SELECT id,program_id,year_level,enrollment_classification FROM students WHERE user_id=$1',[req.user.id])).rows[0],term=(await c.query('SELECT id,enrollment_open FROM academic_terms WHERE is_current LIMIT 1')).rows[0];if(!term?.enrollment_open){const e=new Error('Online enrollment is currently closed.');e.status=400;throw e}const block=(await c.query(`SELECT b.*,COUNT(DISTINCT e.student_id)::int occupied FROM academic_blocks b LEFT JOIN enrollments e ON e.block_id=b.id AND e.status IN('pending','enrolled') WHERE b.id=$1 AND b.term_id=$2 AND b.program_id=$3 AND b.is_active GROUP BY b.id`,[b.block_id,term.id,s.program_id])).rows[0];if(!block||block.classification!==s.enrollment_classification||(s.enrollment_classification==='regular'&&Number(block.year_level)!==Number(s.year_level))){const e=new Error('That section is not available for your program, year level, or recorded enrollment classification.');e.status=400;throw e}if(Number(block.occupied)>=Number(block.capacity)){const e=new Error('The selected section is already full.');e.status=409;throw e}const classes=await c.query(`SELECT cs.id,c.units FROM class_sections cs JOIN courses c ON c.id=cs.course_id WHERE cs.block_id=$1 AND cs.term_id=$2 ORDER BY c.code`,[block.id,term.id]);if(!classes.rowCount){const e=new Error('The selected section has no assigned courses.');e.status=400;throw e}const units=classes.rows.reduce((n,x)=>n+Number(x.units),0);if(units>27){const e=new Error('The section study load exceeds the 27-unit limit. Contact the Registrar.');e.status=400;throw e}const enrollment=(await c.query(`INSERT INTO enrollments(student_id,term_id,status,enrollment_type,total_units,block_id,submitted_at,remarks)VALUES($1,$2,'pending',$3,$4,$5,NOW(),NULL)ON CONFLICT(student_id,term_id)DO UPDATE SET status='pending',enrollment_type=EXCLUDED.enrollment_type,total_units=EXCLUDED.total_units,block_id=EXCLUDED.block_id,submitted_at=NOW(),reviewed_by=NULL,reviewed_at=NULL,remarks=NULL RETURNING *`,[s.id,term.id,s.enrollment_classification,units,block.id])).rows[0];await c.query('DELETE FROM enrollment_items WHERE enrollment_id=$1',[enrollment.id]);for(const row of classes.rows)await c.query('INSERT INTO enrollment_items(enrollment_id,class_section_id)VALUES($1,$2)',[enrollment.id,row.id]);await c.query('UPDATE students SET section=$1 WHERE id=$2',[block.code,s.id]);await c.query('COMMIT');await audit(req.user.id,'SUBMITTED_ENROLLMENT','enrollment',enrollment.id,{type:s.enrollment_classification,section:block.code,units,courses:classes.rowCount});res.status(201).json({...enrollment,section_code:block.code,course_count:classes.rowCount})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));

app.get('/api/teacher/classes',auth,allow('teacher'),wrap(async(req,res)=>res.json((await pool.query(`SELECT cs.id,c.code,c.title,cs.section_code,cs.room,cs.days,TO_CHAR(cs.start_time,'HH12:MI AM')start_time,COUNT(ei.id)::int students,COUNT(ei.id)FILTER(WHERE ei.final_grade IS NULL)::int ungraded FROM teachers t JOIN class_sections cs ON cs.teacher_id=t.id JOIN courses c ON c.id=cs.course_id LEFT JOIN enrollment_items ei ON ei.class_section_id=cs.id WHERE t.user_id=$1 GROUP BY cs.id,c.code,c.title ORDER BY cs.start_time`,[req.user.id])).rows)));
