app.get('/api/registrar/enrollments',auth,allow('registrar','admin'),wrap(async(req,res)=>res.json((await pool.query(`SELECT e.id,e.status,e.enrollment_type,e.total_units,e.submitted_at,e.remarks,b.code section_code,u.employee_or_student_no student_no,u.first_name,u.last_name,p.code program,s.year_level,s.admission_type,at.school_year,at.semester,COUNT(ei.id)::int subjects FROM enrollments e JOIN students s ON s.id=e.student_id JOIN users u ON u.id=s.user_id LEFT JOIN programs p ON p.id=s.program_id JOIN academic_terms at ON at.id=e.term_id LEFT JOIN academic_blocks b ON b.id=e.block_id LEFT JOIN enrollment_items ei ON ei.enrollment_id=e.id GROUP BY e.id,u.id,p.code,s.year_level,s.admission_type,at.id,b.code ORDER BY CASE e.status WHEN 'pending' THEN 1 WHEN 'draft' THEN 2 ELSE 3 END,e.submitted_at DESC`)).rows)));
app.get('/api/registrar/enrollments/:id/items',auth,allow('registrar','admin'),wrap(async(req,res)=>{const enrollment=(await pool.query(`SELECT e.id,e.status,e.enrollment_type,e.total_units,e.remarks,b.code section_code,u.employee_or_student_no student_no,u.first_name,u.last_name,p.code program,s.year_level,at.school_year,at.semester FROM enrollments e JOIN students s ON s.id=e.student_id JOIN users u ON u.id=s.user_id JOIN programs p ON p.id=s.program_id JOIN academic_terms at ON at.id=e.term_id LEFT JOIN academic_blocks b ON b.id=e.block_id WHERE e.id=$1`,[req.params.id])).rows[0];if(!enrollment)return res.status(404).json({message:'Enrollment record not found.'});const courses=(await pool.query(`SELECT c.code,c.title,c.units,cs.room,cs.days,TO_CHAR(cs.start_time,'HH12:MI AM')start_time,TO_CHAR(cs.end_time,'HH12:MI AM')end_time,u.first_name||' '||u.last_name teacher FROM enrollment_items ei JOIN class_sections cs ON cs.id=ei.class_section_id JOIN courses c ON c.id=cs.course_id LEFT JOIN teachers t ON t.id=cs.teacher_id LEFT JOIN users u ON u.id=t.user_id WHERE ei.enrollment_id=$1 ORDER BY cs.start_time,c.code`,[req.params.id])).rows;res.json({enrollment,courses})}));
app.patch('/api/registrar/enrollments/:id',auth,allow('registrar','admin'),wrap(async(req,res)=>{const q=await pool.query('UPDATE enrollments SET status=$1,remarks=$2,reviewed_by=$3,reviewed_at=NOW()WHERE id=$4 RETURNING *',[req.body.status,req.body.remarks||null,req.user.id,req.params.id]);await audit(req.user.id,'REVIEWED_ENROLLMENT','enrollment',req.params.id,{status:req.body.status});res.json(q.rows[0])}));
app.get('/api/registrar/admissions',auth,allow('registrar','admin'),wrap(async(req,res)=>res.json((await pool.query(`SELECT a.*,p.code program_code,p.name program_name FROM admission_applications a JOIN programs p ON p.id=a.program_id ORDER BY CASE a.status WHEN 'submitted' THEN 1 WHEN 'under_review' THEN 2 ELSE 3 END,a.submitted_at DESC`)).rows)));
app.patch('/api/registrar/admissions/:id',auth,allow('registrar','admin'),wrap(async(req,res)=>{const b=req.body;if(!['under_review','approved','rejected'].includes(b.status))return res.status(400).json({message:'Select a valid application status.'});const c=await pool.connect();try{await c.query('BEGIN');const a=(await c.query('SELECT * FROM admission_applications WHERE id=$1 FOR UPDATE',[req.params.id])).rows[0];if(!a){const e=new Error('Application not found.');e.status=404;throw e}let credentials=null,studentId=a.student_id;if(b.status==='approved'&&!studentId){const year=new Date().getFullYear(),studentNo=`${year}-${String(a.id).padStart(5,'0')}`,inactivePassword=crypto.randomBytes(32).toString('hex');const u=(await c.query(`INSERT INTO users(employee_or_student_no,email,password_hash,role,first_name,middle_name,last_name,phone,address)VALUES($1,$2,crypt($3,gen_salt('bf',10)),'student',$4,$5,$6,$7,$8)RETURNING id,email,employee_or_student_no`,[studentNo,a.email,inactivePassword,a.first_name,a.middle_name,a.last_name,a.phone,a.address])).rows[0];studentId=(await c.query(`INSERT INTO students(user_id,program_id,year_level,section,admission_year,birth_date,gender,guardian_name,guardian_phone,admission_type,enrollment_classification)VALUES($1,$2,1,'TBA',$3,$4,$5,$6,$7,$8,CASE WHEN $8::varchar='transferee' THEN 'irregular' ELSE 'regular' END)RETURNING id`,[u.id,a.program_id,year,a.birth_date,a.gender,a.guardian_name,a.guardian_phone,a.applicant_type])).rows[0].id;const term=(await c.query('SELECT id FROM academic_terms WHERE is_current LIMIT 1')).rows[0];if(term)await c.query(`INSERT INTO enrollments(student_id,term_id,status,enrollment_type,total_units,remarks)VALUES($1,$2,'draft',(SELECT enrollment_classification FROM students WHERE id=$1),0,'Complete subject selection in the student portal.')ON CONFLICT(student_id,term_id)DO NOTHING`,[studentId,term.id]);credentials={email:u.email,student_no:u.employee_or_student_no}}await c.query(`UPDATE admission_applications SET status=$1,registrar_notes=$2,student_id=$3,reviewed_by=$4,reviewed_at=NOW(),updated_at=NOW()WHERE id=$5`,[b.status,b.registrar_notes||null,studentId,req.user.id,req.params.id]);await c.query('COMMIT');await audit(req.user.id,'REVIEWED_ADMISSION','admission_application',req.params.id,{status:b.status});res.json({status:b.status,credentials})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.get('/api/registrar/documents',auth,allow('registrar','admin'),wrap(async(req,res)=>res.json((await pool.query(`SELECT d.*,u.employee_or_student_no student_no,u.first_name,u.last_name FROM document_requests d JOIN students s ON s.id=d.student_id JOIN users u ON u.id=s.user_id ORDER BY d.requested_at DESC`)).rows)));
app.patch('/api/registrar/documents/:id',auth,allow('registrar','admin'),wrap(async(req,res)=>{const q=await pool.query(`UPDATE document_requests SET status=$1,notes=$2,processed_by=$3,released_at=CASE WHEN $1='released' THEN NOW()ELSE released_at END WHERE id=$4 RETURNING *`,[req.body.status,req.body.notes||null,req.user.id,req.params.id]);await audit(req.user.id,'UPDATED_DOCUMENT_REQUEST','document_request',req.params.id,{status:req.body.status});res.json(q.rows[0])}));

app.get('/api/cashier/accounts',auth,allow('cashier','admin'),wrap(async(req,res)=>res.json((await pool.query(`SELECT b.id,b.student_id,b.description,b.category,b.amount,b.due_date,b.status,b.notes,u.employee_or_student_no student_no,u.first_name,u.last_name,COALESCE(SUM(p.amount)FILTER(WHERE p.status='posted'),0)paid FROM billing_items b JOIN students s ON s.id=b.student_id JOIN users u ON u.id=s.user_id LEFT JOIN payments p ON p.billing_item_id=b.id GROUP BY b.id,u.id ORDER BY b.created_at DESC`)).rows)));
app.get('/api/cashier/payments',auth,allow('cashier','admin'),wrap(async(req,res)=>res.json((await pool.query(`SELECT p.id,p.amount,p.payment_method,p.reference_no,p.paid_at,p.status,p.voided_at,p.void_reason,b.description,u.employee_or_student_no student_no,u.first_name,u.last_name,staff.first_name||' '||staff.last_name received_by_name FROM payments p JOIN students s ON s.id=p.student_id JOIN users u ON u.id=s.user_id LEFT JOIN billing_items b ON b.id=p.billing_item_id LEFT JOIN users staff ON staff.id=p.received_by ORDER BY p.paid_at DESC LIMIT 200`)).rows)));
app.post('/api/cashier/assessments',auth,allow('cashier','admin'),wrap(async(req,res)=>{const b=req.body;if(!b.student_id||!b.description||!b.category||!b.amount||Number(b.amount)<=0)return res.status(400).json({message:'Student, description, category, and a positive amount are required.'});const term=(await pool.query('SELECT id FROM academic_terms WHERE is_current LIMIT 1')).rows[0];const q=await pool.query(`INSERT INTO billing_items(student_id,term_id,description,category,amount,due_date,status,created_by,notes)VALUES($1,$2,$3,$4,$5,$6,'Unpaid',$7,$8)RETURNING *`,[b.student_id,term?.id||null,b.description,b.category,b.amount,b.due_date||null,req.user.id,b.notes||null]);await audit(req.user.id,'CREATED_ASSESSMENT','billing_item',q.rows[0].id,{amount:b.amount});res.status(201).json(q.rows[0])}));
app.post('/api/cashier/payments',auth,allow('cashier','admin'),wrap(async(req,res)=>{const b=req.body,c=await pool.connect();try{await c.query('BEGIN');const bill=(await c.query('SELECT * FROM billing_items WHERE id=$1 FOR UPDATE',[b.billing_item_id])).rows[0];if(!bill){const e=new Error('Billing item not found.');e.status=404;throw e}const paid=Number((await c.query(`SELECT COALESCE(SUM(amount),0)total FROM payments WHERE billing_item_id=$1 AND status='posted'`,[bill.id])).rows[0].total),amount=Number(b.amount),balance=Number(bill.amount)-paid;if(!Number.isFinite(amount)||amount<=0){const e=new Error('Payment amount must be greater than zero.');e.status=400;throw e}if(amount>balance){const e=new Error(`Payment exceeds the outstanding balance of ${balance.toFixed(2)}.`);e.status=400;throw e}if(!b.payment_method||!b.reference_no){const e=new Error('Payment method and official reference number are required.');e.status=400;throw e}const q=await c.query(`INSERT INTO payments(billing_item_id,student_id,amount,payment_method,reference_no,received_by,status)VALUES($1,$2,$3,$4,$5,$6,'posted')RETURNING *`,[bill.id,bill.student_id,amount,b.payment_method,b.reference_no.trim(),req.user.id]);const total=paid+amount,newStatus=total>=Number(bill.amount)?'Paid':'Partial';await c.query('UPDATE billing_items SET status=$1 WHERE id=$2',[newStatus,bill.id]);await c.query('COMMIT');await audit(req.user.id,'RECORDED_PAYMENT','payment',q.rows[0].id,{reference_no:b.reference_no,amount});res.status(201).json({...q.rows[0],balance:Number(bill.amount)-total,billing_status:newStatus})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.patch('/api/cashier/payments/:id/void',auth,allow('cashier','admin'),wrap(async(req,res)=>{if(!req.body.reason)return res.status(400).json({message:'A void reason is required.'});const c=await pool.connect();try{await c.query('BEGIN');const payment=(await c.query(`SELECT * FROM payments WHERE id=$1 FOR UPDATE`,[req.params.id])).rows[0];if(!payment){const e=new Error('Payment not found.');e.status=404;throw e}if(payment.status==='void'){const e=new Error('This payment is already void.');e.status=409;throw e}await c.query(`UPDATE payments SET status='void',voided_by=$1,voided_at=NOW(),void_reason=$2 WHERE id=$3`,[req.user.id,req.body.reason,payment.id]);const bill=await c.query(`SELECT b.amount,COALESCE(SUM(p.amount)FILTER(WHERE p.status='posted'),0)paid FROM billing_items b LEFT JOIN payments p ON p.billing_item_id=b.id WHERE b.id=$1 GROUP BY b.id`,[payment.billing_item_id]),x=bill.rows[0],status=Number(x.paid)>=Number(x.amount)?'Paid':Number(x.paid)>0?'Partial':'Unpaid';await c.query('UPDATE billing_items SET status=$1 WHERE id=$2',[status,payment.billing_item_id]);await c.query('COMMIT');await audit(req.user.id,'VOIDED_PAYMENT','payment',payment.id,{reason:req.body.reason});res.json({id:payment.id,status:'void',billing_status:status})}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}));
app.get('/api/clinic/visits',auth,allow('clinic','admin'),wrap(async(req,res)=>res.json((await pool.query(`SELECT v.*,u.employee_or_student_no student_no,u.first_name,u.last_name,staff.first_name||' '||staff.last_name attended_by_name FROM clinic_visits v JOIN students s ON s.id=v.student_id JOIN users u ON u.id=s.user_id LEFT JOIN users staff ON staff.id=v.attended_by ORDER BY v.visited_at DESC`)).rows)));
app.post('/api/clinic/visits',auth,allow('clinic','admin'),wrap(async(req,res)=>{const b=req.body;if(!b.student_id||!b.complaint)return res.status(400).json({message:'Student and complaint are required.'});const q=await pool.query('INSERT INTO clinic_visits(student_id,attended_by,complaint,assessment,treatment,disposition,vital_signs)VALUES($1,$2,$3,$4,$5,$6,$7)RETURNING *',[b.student_id,req.user.id,b.complaint,b.assessment||null,b.treatment||null,b.disposition||'Returned to class',b.vital_signs||{}]);await audit(req.user.id,'RECORDED_CLINIC_VISIT','clinic_visit',q.rows[0].id);res.status(201).json(q.rows[0])}));

const frontendDir=path.join(__dirname,'../frontend/dist');
app.use(express.static(frontendDir)); app.get('*path',(req,res)=>res.sendFile(path.join(frontendDir,'index.html')));
app.use((error,req,res,next)=>{console.error(error);const s=error.status||(/duplicate key/.test(error.message)?409:500);res.status(s).json({message:s===500?'Something went wrong while processing your request.':error.message})});
app.listen(PORT,()=>console.log(`CTU Main Campus portal running at http://localhost:${PORT}`));
